<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { canGovernance as can } from '../../governance/permissions.js'
import { createClientId } from '../../clientId.js'
import SourceFieldBinding from './SourceFieldBinding.vue'
import { governanceWrite } from '../../governance/api.js'
import { conflictMessage, label, recordBody } from '../../governance/helpers.js'
const props=defineProps({configs:Object,devices:Array})
const emit=defineEmits(['refresh'])
const kind=ref('templates'), dialog=ref(false), saving=ref(false), error=ref(''), validation=ref(null), form=reactive({}), revisionId=ref(''),newRevision=ref(false)
const rows=computed(()=>(props.configs[kind.value]||[]).map(recordBody))
const titles={templates:'通用模板','scene-presets':'场景预设','type-profiles':'报警类型配置'}
function edit(row,copy=false,append=false){newRevision.value=append;const base=row||((kind.value==='templates'&&(props.configs.templates||[]).map(recordBody).find(item=>item.builtin))||{});const value=JSON.parse(JSON.stringify(base));Object.assign(form,{resourceId:copy?createClientId():value.resourceId||createClientId(),name:copy?`${value.name}（副本）`:value.name||'',schemaVersion:value.schemaVersion||'1',status:'DRAFT',fields:value.fields||[],applicableAlarmTypes:value.applicableAlarmTypes||[],activityOptions:value.activityOptions||[],environmentOptions:value.environmentOptions||[],facilityQuestions:value.facilityQuestions||[],requiredEvidence:value.requiredEvidence||[],deviceIds:value.deviceIds||[],productId:value.productId||'',alarmType:value.alarmType||'',originKind:value.originKind||'',signalKey:value.signalKey||'',cycleMethod:value.cycleMethod||'REPORT_ONLY',timeBasis:value.timeBasis||'UNKNOWN',recoverySemantics:value.recoverySemantics||'',referenceBasis:value.referenceBasis||'',expectedVersion:copy?0:row?.version||0,idempotencyKey:createClientId()});revisionId.value=copy||append?'':row?.id||'';validation.value=null;error.value='';dialog.value=true}
async function save(){if(saving.value||!can(`${revisionId.value?'PATCH':'POST'} /api/v1/alarm-governance/${kind.value}${revisionId.value?'/:id/revisions/:revisionId':''}`))return; saving.value=true;error.value='';try{if(!form.name.trim())throw new Error('请填写配置名称');const value=revisionId.value?await governanceWrite(kind.value,form.resourceId,`revisions/${encodeURIComponent(revisionId.value)}`,form,'PATCH'):await governanceWrite(kind.value,newRevision.value?form.resourceId:'',newRevision.value?'revisions':'',form);const row=recordBody(value);revisionId.value=row.id;form.expectedVersion=row.version;form.idempotencyKey=createClientId();emit('refresh');validation.value=null}catch(cause){error.value=conflictMessage(cause)}finally{saving.value=false}}
async function action(row,operation){if(saving.value||!can(`POST /api/v1/alarm-governance/${kind.value}/:id/revisions/:revisionId/${operation}`))return;saving.value=true;error.value='';try{const result=await governanceWrite(kind.value,row.resourceId,`revisions/${encodeURIComponent(row.id)}/${operation}`,{expectedVersion:row.version,idempotencyKey:createClientId()});if(operation==='validate')validation.value={valid:true,affectedDeviceIds:result.body?.deviceIds||[],message:result.body?.deviceIds?.length?`明确影响 ${result.body.deviceIds.length} 台设备`:'共享配置：影响完整租户授权范围，服务端已核对操作人范围'};else{emit('refresh');dialog.value=false}}catch(cause){error.value=conflictMessage(cause)}finally{saving.value=false}}
watch(form,()=>validation.value=null,{deep:true})
const inputTypes=['text','single','multi','time','number','attachment']
</script>
<template><section class="gov-stack"><div class="gov-toolbar"><ui-select v-model="kind" class="gov-compact"><ui-option v-for="[code,title] in Object.entries(titles)" :key="code" :value="code" :label="title"/></ui-select><ui-button v-if="can(`POST /api/v1/alarm-governance/${kind}`)" size="small" @click="edit()">新建租户配置</ui-button></div><ui-alert v-if="error&&!dialog" :title="error" type="error" :closable="false"/><p class="gov-meta">内置通用模板与七种场景只读。复制为租户草稿后可编辑，发布新版本保留旧轮次取证语义。</p><div class="gov-cards"><article v-for="row in rows" :key="row.id" class="gov-card"><div class="gov-toolbar"><strong>{{row.name}}</strong><ui-tag :type="tone(row.status)">{{label(row.status)}} · {{row.builtin?'内置只读':'租户配置'}}</ui-tag></div><p class="gov-meta">版本 {{row.revisionNumber}} · {{row.fields?.length||0}} 个字段 · {{row.deviceIds?.length||0}} 台明确设备<span v-if="row.cycleMethod"> · {{label(row.cycleMethod)}}</span></p><p class="gov-meta">{{row.referenceBasis||'依据未补充'}} · 原始类型 {{row.alarmType||'按具体信号'}} </p><div class="gov-actions"><ui-button v-if="can(`POST /api/v1/alarm-governance/${kind}`)" text size="small" @click="edit(row,true)">复制为草稿</ui-button><ui-button v-if="!row.builtin&&row.status==='DRAFT'&&can(`PATCH /api/v1/alarm-governance/${kind}/:id/revisions/:revisionId`)" text size="small" @click="edit(row)">编辑草稿</ui-button><ui-button v-if="!row.builtin&&can(`POST /api/v1/alarm-governance/${kind}/:id/revisions`)" text size="small" @click="edit(row,false,true)">追加草稿版本</ui-button><ui-button v-if="!row.builtin&&row.status==='PUBLISHED'&&can(`POST /api/v1/alarm-governance/${kind}/:id/revisions/:revisionId/retire`)" text size="small" @click="action(row,'retire')">退休版本</ui-button></div><details><summary>固定字段与选项</summary><p v-for="field in row.fields||[]" :key="field.id" class="gov-meta">{{field.label}} · {{field.required?'必填':'选填'}} {{field.protected?'· 保护字段':''}} · {{(field.options||[]).map(option=>option.label).join(' / ')}}</p></details></article></div><ui-empty v-if="!rows.length" description="尚无配置。"/></section>
<ui-dialog v-model="dialog" :title="`${titles[kind]}草稿`" width="min(900px,94vw)" :close-on-click-modal="false"><div class="gov-dialog-body"><ui-alert v-if="error" :title="error" type="error" :closable="false"/><ui-form label-position="top" :disabled="saving"><div class="gov-grid"><ui-form-item label="配置名称" required><ui-input v-model="form.name"/></ui-form-item><ui-form-item label="明确影响设备"><ui-select v-model="form.deviceIds" multiple filterable><ui-option v-for="row in devices" :key="row.id" :value="row.id" :label="row.name||row.id"/></ui-select></ui-form-item><ui-form-item label="适用报警类型"><ui-select v-model="form.applicableAlarmTypes" multiple filterable allow-create><ui-option v-for="code in ['FIRE','FAULT','SUPERVISORY']" :key="code" :value="code" :label="code"/></ui-select></ui-form-item><ui-form-item label="资料 / 现场依据"><ui-input v-model="form.referenceBasis"/></ui-form-item><template v-if="kind==='type-profiles'"><ui-form-item label="原始报警类型" required><ui-input v-model="form.alarmType"/></ui-form-item><ui-form-item label="来源语义" required><ui-select v-model="form.originKind"><ui-option v-for="code in ['COMPONENT_STATE','DEVICE_DIRECT','RULE_LIFECYCLE']" :key="code" :value="code" :label="label(code)"/></ui-select></ui-form-item><ui-form-item label="明确信号键"><ui-input v-model="form.signalKey"/></ui-form-item><ui-form-item label="周期重建口径"><ui-select v-model="form.cycleMethod"><ui-option v-for="code in ['REPORT_ONLY','COMPONENT_BOOLEAN','DIRECT_EXPLICIT_STATE','RECORDED_RULE_LIFECYCLE']" :key="code" :value="code" :label="label(code)"/></ui-select></ui-form-item><ui-form-item label="时间依据"><ui-select v-model="form.timeBasis"><ui-option value="UNKNOWN" label="未知"/><ui-option value="EVENT_AT" label="可信来源事件时间"/><ui-option value="RECEIVED_AT" label="平台接收分布"/></ui-select></ui-form-item><ui-form-item label="明确恢复语义"><ui-input v-model="form.recoverySemantics"/></ui-form-item></template></div><h3>取证字段</h3><article v-for="(field,index) in form.fields" :key="index" class="gov-card"><div class="gov-grid"><ui-form-item label="稳定字段 ID"><ui-input v-model="field.id" :disabled="field.protected"/></ui-form-item><ui-form-item label="字段名称"><ui-input v-model="field.label" :disabled="field.protected"/></ui-form-item><ui-form-item label="控件"><ui-select v-model="field.control" :disabled="field.protected"><ui-option v-for="code in inputTypes" :key="code" :value="code" :label="{text:'文字',single:'单选',multi:'多选',time:'时间',number:'有限数值',attachment:'附件'}[code]"/></ui-select></ui-form-item><ui-form-item v-if="field.control==='number'" label="有限数值范围"><div class="gov-grid"><ui-input-number v-model="field.min" placeholder="最小值"/><ui-input-number v-model="field.max" placeholder="最大值"/></div></ui-form-item><ui-form-item label="校验"><ui-checkbox v-model="field.required" :disabled="field.protected">必填</ui-checkbox></ui-form-item></div><div v-for="(option,optionIndex) in field.options||[]" :key="optionIndex" class="gov-toolbar"><ui-input v-model="option.code" :disabled="field.protected" placeholder="稳定选项代码"/><ui-input v-model="option.label" :disabled="field.protected" placeholder="中文选项名称"/><ui-button v-if="!field.protected" text size="small" @click="field.options.splice(optionIndex,1)">移除</ui-button></div><SourceFieldBinding :field="field" :devices="devices"/><div class="gov-actions"><ui-button v-if="!field.protected" text size="small" @click="field.options ||= [];field.options.push({code:'',label:''})">添加选项</ui-button><ui-button v-if="!field.protected" text size="small" @click="form.fields.splice(index,1)">删除字段</ui-button><span v-else class="gov-meta">未知、争议与现场原始记录为保护字段</span></div></article><ui-button size="small" @click="form.fields.push({id:'',label:'',control:'text',required:false,protected:false,options:[]})">添加取证字段</ui-button><ui-form-item v-if="kind==='scene-presets'" label="活动选项"><div class="gov-stack"><div v-for="(option,index) in form.activityOptions" :key="index" class="gov-toolbar"><ui-input v-model="option.code" placeholder="稳定活动代码"/><ui-input v-model="option.label" placeholder="中文名称"/><ui-button text size="small" @click="form.activityOptions.splice(index,1)">移除</ui-button></div><ui-button size="small" @click="form.activityOptions.push({code:'',label:''})">添加活动选项</ui-button></div></ui-form-item><ui-form-item v-if="kind==='scene-presets'" label="环境选项"><div class="gov-stack"><div v-for="(option,index) in form.environmentOptions" :key="index" class="gov-toolbar"><ui-input v-model="option.code" placeholder="稳定环境代码"/><ui-input v-model="option.label" placeholder="中文名称"/><ui-button text size="small" @click="form.environmentOptions.splice(index,1)">移除</ui-button></div><ui-button size="small" @click="form.environmentOptions.push({code:'',label:''})">添加环境选项</ui-button></div></ui-form-item><div v-if="kind==='scene-presets'" class="gov-stack"><h3>关联设施检查问题</h3><article v-for="(field,index) in form.facilityQuestions" :key="index" class="gov-card"><div class="gov-grid"><ui-form-item label="稳定问题 ID"><ui-input v-model="field.id" :disabled="field.protected"/></ui-form-item><ui-form-item label="设施问题"><ui-input v-model="field.label" :disabled="field.protected"/></ui-form-item><ui-form-item label="控件"><ui-select v-model="field.control" :disabled="field.protected"><ui-option v-for="code in inputTypes" :key="code" :value="code" :label="{text:'文字',single:'单选',multi:'多选',time:'时间',number:'有限数值',attachment:'附件'}[code]"/></ui-select></ui-form-item><ui-form-item label="是否必填"><ui-checkbox v-model="field.required" :disabled="field.protected">必填</ui-checkbox></ui-form-item></div><div v-for="(option,optionIndex) in field.options||[]" :key="optionIndex" class="gov-toolbar"><ui-input v-model="option.code" :disabled="field.protected" placeholder="稳定选项代码"/><ui-input v-model="option.label" :disabled="field.protected" placeholder="中文选项名称"/><ui-button v-if="!field.protected" text size="small" @click="field.options.splice(optionIndex,1)">移除</ui-button></div><SourceFieldBinding :field="field" :devices="devices"/><div v-if="!field.protected" class="gov-actions"><ui-button text size="small" @click="field.options ||= [];field.options.push({code:'',label:''})">添加选项</ui-button><ui-button text size="small" @click="form.facilityQuestions.splice(index,1)">移除问题</ui-button></div></article><ui-button size="small" @click="form.facilityQuestions.push({id:'',label:'',control:'single',required:false,protected:false,options:[{code:'UNKNOWN',label:'未知'}]})">添加设施检查问题</ui-button></div></ui-form><ui-alert v-if="validation" :type="validation.valid===false?'warning':'info'" :closable="false"><strong>服务端验证与影响预览</strong><p class="gov-meta">{{validation.message||`明确影响 ${validation.affectedDeviceIds?.length||form.deviceIds.length} 台设备`}}</p><p v-for="issue in validation.errors||validation.issues||[]" :key="JSON.stringify(issue)">{{typeof issue==='string'?issue:issue.message}}</p></ui-alert></div><template #footer><ui-button :disabled="saving" @click="dialog=false">关闭</ui-button><ui-button :loading="saving" @click="save">保存草稿</ui-button><ui-button v-if="revisionId" :loading="saving" @click="action({...form,id:revisionId,version:form.expectedVersion},'validate')">校验与影响预览</ui-button><ui-button v-if="revisionId&&validation?.valid!==false&&validation&&can(`POST /api/v1/alarm-governance/${kind}/:id/revisions/:revisionId/publish`)" type="primary" :loading="saving" @click="action({...form,id:revisionId,version:form.expectedVersion},'publish')">发布固定版本</ui-button></template></ui-dialog>
</template>
<script>
import { tone } from '../../governance/helpers.js'
export default { methods:{tone} }
</script>
